-- Synthetic restaurant point-of-sale schema used by the plan-guard demo, lab and integration tests.
-- All data is generated by seed.sql; nothing here comes from a real system.

CREATE EXTENSION IF NOT EXISTS pg_stat_statements;

CREATE TABLE stores (
    id         int  PRIMARY KEY,
    city       text NOT NULL,
    opened_on  date NOT NULL
);

CREATE TABLE customers (
    id         int         PRIMARY KEY,
    email      text        NOT NULL,
    phone      text        NOT NULL,
    city       text        NOT NULL,
    created_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX customers_email_lower_key ON customers (lower(email));

CREATE TABLE menu_items (
    id         int           PRIMARY KEY,
    store_id   int           NOT NULL REFERENCES stores,
    name       text          NOT NULL,
    category   text          NOT NULL,
    price      numeric(10,2) NOT NULL
);
CREATE INDEX menu_items_store_idx ON menu_items (store_id);

CREATE TABLE orders (
    id          bigint        PRIMARY KEY,
    store_id    int           NOT NULL REFERENCES stores,
    customer_id int           REFERENCES customers,
    status      text          NOT NULL CHECK (status IN ('open', 'paid', 'cancelled')),
    total       numeric(12,2) NOT NULL,
    created_at  timestamptz   NOT NULL
);
CREATE INDEX orders_customer_idx      ON orders (customer_id, created_at DESC);
CREATE INDEX orders_store_created_idx ON orders (store_id, created_at);
CREATE INDEX orders_open_idx          ON orders (created_at) WHERE status = 'open';

CREATE TABLE order_items (
    id           bigint        GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id     bigint        NOT NULL REFERENCES orders,
    line_no      int           NOT NULL,
    menu_item_id int           NOT NULL REFERENCES menu_items,
    qty          int           NOT NULL CHECK (qty > 0),
    unit_price   numeric(10,2) NOT NULL
);
CREATE INDEX order_items_order_idx     ON order_items (order_id);
CREATE INDEX order_items_menu_item_idx ON order_items (menu_item_id);
